# Before every build: the web page (WEB_UI in src/main.cpp) gzip-compressed into <build>/gen/webui_gz.h, so the T-Deck
# sends about a quarter of the bytes and the radio loop stops for less time. The page source stays readable in
# main.cpp; this file is generated, never edited by hand.
import gzip
import os
import re

Import("env")  # noqa: F821  (PlatformIO)

ROOT = env.subst("$PROJECT_DIR")  # noqa: F821
SRC = os.path.join(ROOT, "src", "main.cpp")
GEN = os.path.join(env.subst("$BUILD_DIR"), "gen")  # noqa: F821  (outside src: never published)
OUT = os.path.join(GEN, "webui_gz.h")
os.makedirs(GEN, exist_ok=True)
env.Append(CPPPATH=[GEN])  # noqa: F821


def build():
    s = open(SRC, encoding="utf-8").read()
    ver = re.search(r'#define FW_VERSION "([^"]+)"', s).group(1)
    beta = int(re.search(r"#define FW_BETA (\d+)", s).group(1))
    name = ver + ("-beta%d" % beta if beta else "")
    flags = os.environ.get("PLATFORMIO_BUILD_FLAGS", "")
    if "PRED_SERVER_ALLOW_HTTP=1" in flags:
        name += "-test"  # as FW_NAME in main.cpp
    doc = re.search(r'#define SH_DOC_URL "([^"]+)"', s).group(1)
    i = s.index('static const char WEB_UI[] = R"HTML(') + len('static const char WEB_UI[] = R"HTML(')
    j = s.index(')HTML";', i)
    page = s[i:j]
    page = page.replace(')HTML" FW_NAME R"HTML(', name).replace(')HTML" SH_DOC_URL R"HTML(', doc)
    if ')HTML"' in page:
        raise RuntimeError("web_gz.py: unknown macro spliced into WEB_UI")
    gz = gzip.compress(page.encode("utf-8"), compresslevel=9, mtime=0)
    lines = ["// Generated by tools/web_gz.py from WEB_UI in main.cpp: do not edit.",
             "#pragma once",
             "#define WEB_UI_GZ_ETAG \"\\\"%s-%08x\\\"\"" % (name, gzip_crc(gz)),
             "static const uint8_t WEB_UI_GZ[%d] = {" % len(gz)]
    for k in range(0, len(gz), 20):
        lines.append("    " + ",".join("%d" % b for b in gz[k:k + 20]) + ",")
    lines.append("};")
    text = "\n".join(lines) + "\n"
    if not os.path.exists(OUT) or open(OUT, encoding="utf-8").read() != text:
        open(OUT, "w", encoding="utf-8", newline="\n").write(text)
    print("web_gz: page %d bytes, gzip %d bytes" % (len(page), len(gz)))


def gzip_crc(gz):
    return int.from_bytes(gz[-8:-4], "little")  # CRC-32 of the page, from the gzip trailer


build()
